/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type AddSpecInput = {
  body: string;
  /** Slug of the feature to add it to. */
  feature: string;
  /** File to write it to; derived from the title when absent. */
  fileName?: string | null | undefined;
  title: string;
};

export type CreateFeatureInput = {
  /** Directory to file it under; derived from the title when absent. */
  slug?: string | null | undefined;
  /** Markdown summary; a feature may have none. */
  summary?: string | null | undefined;
  title: string;
};

export type Kind =
  | 'ISSUE'
  | 'PR';

export type ReviewDecision =
  | 'APPROVED'
  | 'CHANGES_REQUESTED'
  | 'PENDING';

/** Issues are open or closed; pull requests may also be merged (spec 02 §2.1). */
export type Status =
  | 'CLOSED'
  | 'MERGED'
  | 'OPEN';

export type UpdateFeatureInput = {
  /**
   * The `baseSha` the editor started from.
   *
   * A save is refused with `STALE_CONTENT` when a field it names has changed
   * since, rather than landed on top of the change that moved it (spec 06 §6.3)
   * — and only then, so a summary saved just after the same page saved the
   * title still lands. As on `UpdateIssueInput`, the refusal lists the fields
   * that moved in `extensions.moved`, and a token this server cannot resolve is
   * stale by definition.
   */
  baseSha: string;
  slug: string;
  summary?: string | null | undefined;
  title?: string | null | undefined;
};

/** Fields to change on a document; `title` and `body` are replaced, never cleared. */
export type UpdateSpecInput = {
  /** See `UpdateFeatureInput.baseSha`. */
  baseSha: string;
  body?: string | null | undefined;
  feature: string;
  fileName: string;
  title?: string | null | undefined;
};

